#!/usr/bin/python3

import pyrob.core as rob
from pyrob.tasks import check_filled_cells, find_cells_to_be_filled


class Task:
    CHECKS = 1

    def load_level(self, n):
        rob.set_field_size(4, 7)
        idx = 0
        if idx == 0:
            rob.set_cell_type(0, 1, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(0, 2, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(0, 3, rob.CELL_TO_BE_FILLED)
            rob.set_cell_type(0, 4, rob.CELL_TO_BE_FILLED)
            rob.goto(0, 0)
            rob.put_wall(bottom=True)
            rob.goto(0, 1)
            rob.put_wall(bottom=True)
            rob.goto(0, 2)
            rob.put_wall(bottom=True)
            rob.goto(0, 3)
            rob.put_wall(bottom=True)
            rob.goto(0, 4)
            rob.put_wall(bottom=True)
            rob.set_parking_cell(0, 0)
            rob.goto(1, 1)

        self.cells_to_fill = find_cells_to_be_filled()

    def check_solution(self):
        return check_filled_cells(self.cells_to_fill) and rob.is_parking_point()
